        if (paginate) {
            return await this.fetchPaginatedCallCursor('fetchTrades', symbol, since, limit, params, 'idLessThan', 'idLessThan');
        }
        const sandboxMode = this.safeValue(this.options, 'sandboxMode', false);
        let market = undefined;
