    parseMarket(market) {
        const id = this.safeString(market, 'name');
        const baseId = this.safeString(market, 'currency1');
        const quoteId = this.safeString(market, 'currency2');
        const base = this.safeCurrencyCode(baseId);
        const quote = this.safeCurrencyCode(quoteId);
        const pricePrecision = this.safeString(market, 'price_precision');
        const priceLimit = this.parsePrecision(pricePrecision);
        const amountLimit = this.safeString(market, 'minimum_order_size');
        return {
            'id': id,
            'symbol': base + '/' + quote,
            'base': base,
            'quote': quote,
            'settle': undefined,
            'baseId': baseId,
            'quoteId': quoteId,
            'settleId': undefined,
            'type': 'spot',
            'spot': true,
            'margin': false,
            'swap': false,
            'future': false,
            'option': false,
            'active': true,
            'contract': false,
            'linear': undefined,
            'inverse': undefined,
            'contractSize': undefined,
            'expiry': undefined,
            'expiryDatetime': undefined,
            'strike': undefined,
            'optionType': undefined,
            'precision': {
                'amount': this.parseNumber(this.parsePrecision(this.safeString(market, 'amount_precision'))),
                'price': this.parseNumber(this.parsePrecision((pricePrecision))),
            },
            'limits': {
                'leverage': {
                    'min': undefined,
                    'max': undefined,
                },
                'amount': {
                    'min': this.parseNumber(amountLimit),
                    'max': this.safeNumber(market, 'maximum_order_size'),
                },
                'price': {
                    'min': this.parseNumber(priceLimit),
                    'max': undefined,
                },
                'cost': {
                    'min': this.parseNumber(Precise.stringMul(priceLimit, amountLimit)),
                    'max': undefined,
                },
            },
            'created': undefined,
            'info': market,
        };
    }
